let S = {
  champ: null,
  year: null,
  tab: 'master',
  openDept: null,
  activeLoc: {},
  openTeam: null,
  activeTeamLoc: {},
  data: null,
  years: { f1: [2025,2026,2027], wec: [2026,2027], motogp: [2025,2026] },
  charts: {}
};

const CHAMP_COLORS = { f1:'#e10600', wec:'#0067ff', motogp:'#ff6900' };
const CHAMP_NAMES  = { f1:'Formula 1', wec:'WEC', motogp:'Moto GP' };
const DEPT_COLORS  = ['#e10600','#0067ff','#ff6900','#00c853','#aa00ff','#ffab00','#00bcd4','#ff4081','#64dd17','#f06292','#29b6f6','#ff7043','#9ccc65','#ab47bc','#26c6da'];

// ── PERSIST ──
function storageKey(champ, year) { return `lic_ffe_${champ}_${year}`; }

function save() {
  if (!S.champ || !S.year || !S.data) return;
  try {
    localStorage.setItem(storageKey(S.champ, S.year), JSON.stringify(S.data));
    localStorage.setItem('lic_ffe_years', JSON.stringify(S.years));
    S._dirty = false;
  } catch(e) {
    if (!save._warned) {
      save._warned = true;
      setTimeout(() => showToast('Storage full — some changes may not persist', 'error'), 100);
    }
  }
}

// Debounced save — call after every data mutation to guarantee persistence
let _saveTimer = null;
function debouncedSave() {
  if (_saveTimer) clearTimeout(_saveTimer);
  _saveTimer = setTimeout(() => { save(); _saveTimer = null; }, 400);
}

// Save on visibility change, tab close, and every 5 s
document.addEventListener('visibilitychange', () => { if (document.hidden) save(); });
window.addEventListener('beforeunload', () => { if (_saveTimer) clearTimeout(_saveTimer); save(); });
setInterval(() => { if (S.champ && S.data) save(); }, 5000);
function loadData(champ, year) {
  const key = storageKey(champ, year);
  try {
    const raw = localStorage.getItem(key);
    if (raw) {
      const parsed = JSON.parse(raw);
      // Basic sanity check — must have items and departments
      if (parsed && parsed.items && parsed.departments) return parsed;
    }
  } catch(e) {}
  // No valid saved data — clone from INITIAL_DATA and immediately persist it
  const fresh = JSON.parse(JSON.stringify(INITIAL_DATA.championships[champ] || INITIAL_DATA.championships.f1));
  try { localStorage.setItem(key, JSON.stringify(fresh)); } catch(e) {}
  return fresh;
}
function loadYears() {
  try {
    const raw = localStorage.getItem('lic_ffe_years');
    if (raw) S.years = JSON.parse(raw);
  } catch(e){}
}

